import { Project } from "../domain/project";
import { ProjectRepository, TaskFilter, TaskRepository, UserRepository } from "../domain/repositories";
import { Task } from "../domain/task";
import { User } from "../domain/user";

export class InMemoryProjectRepository implements ProjectRepository {
  private readonly items = new Map<string, Project>();
  public save(project: Project): void { this.items.set(project.id, project); }
  public findById(id: string): Project | undefined { return this.items.get(id); }
}

export class InMemoryUserRepository implements UserRepository {
  private readonly items = new Map<string, User>();
  public save(user: User): void { this.items.set(user.id, user); }
  public existsById(id: string): boolean { return this.items.has(id); }
}

export class InMemoryTaskRepository implements TaskRepository {
  private readonly items = new Map<string, Task>();
  public save(task: Task): void { this.items.set(task.id, task); }
  public findById(id: string): Task | undefined { return this.items.get(id); }
  public findByProjectId(projectId: string, filter: TaskFilter): Task[] {
    return [...this.items.values()].filter((task) => task.projectId === projectId && (filter.status === undefined || task.status === filter.status) && (filter.assigneeId === undefined || task.assigneeId === filter.assigneeId));
  }
}

